#!/usr/bin/env node
/**
 * Generates ops/evidence/privilege-model-production-assert.sql from the security lab.
 *
 *   node scripts/security-lab/gen-production-assert.mjs <lab-lines.txt> [--check]
 *
 * <lab-lines.txt> is the output of scripts/security-lab/privilege-model.sql on a lab built by build-lab.sh
 * (`SELECT line FROM model ORDER BY line COLLATE "C"`). The generated file embeds privilege-model.sql verbatim and
 * compares Production, section by section, with the lab: md5 of the section's lines joined by "\n" in byte order.
 * The repository is public, so the file prints only PASS / FAIL, counts and booleans (scripts/ci/evidence-output-guard).
 *
 * Expected Production differences are asserted one by one instead of being hashed:
 *   * EXTRA lines — privileges that exist outside the migrations (scripts/security/d2-*-grants.sql, applied by hand);
 *     each is reported as present / absent so a FAIL in section G or S can be read without printing a row.
 *   * section L (privileges held directly by a LOGIN role) and B (BYPASSRLS roles) are counted, not hashed.
 * --check: exit 1 when the committed file differs from what would be generated (CI keeps it current).
 */
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1")), "../..");
const OUT = path.join(ROOT, "ops/evidence/privilege-model-production-assert.sql");
const MODEL = fs.readFileSync(path.join(ROOT, "scripts/security-lab/privilege-model.sql"), "utf8").replace(/\r\n/g, "\n");

/** Privileges the D2 control-plane / admin-read rollout applied outside the migrations (Preview has them). */
export const EXTRA = [
  "G|BillingDocument|app_admin|r", "G|BusinessFeatureAccess|app_ctlplane|w", "G|Business|app_admin|r",
  "G|Business|app_ctlplane|r", "G|ContentRun|app_admin|r", "G|Conversation|app_admin|r", "G|Document|app_admin|r",
  "G|EmailConnection|app_admin|r", "G|ExtractionEvidence|app_admin|r", "G|ExtractionSnapshot|app_admin|r",
  "G|FinancialRecord|app_admin|r", "G|PlatformAuditEvent|app_admin|a", "G|PlatformFeaturePolicy|app_admin|r",
  "G|ReviewEvent|app_admin|r", "G|SliceDecision|app_admin|r", "G|WhatsAppAttachmentImport|app_admin|r",
  "S|PlatformAuditEvent_id_seq|app_admin|U", "S|PlatformAuditEvent_id_seq|app_admin|r",
];

const SECTIONS = [
  ["T", "tables_rls_flags"], ["P", "policies"], ["G", "table_privileges"], ["C", "column_privileges"],
  ["S", "sequence_privileges"], ["F", "security_definer_functions"], ["X", "function_execute"],
  ["D", "owner_default_privileges"],
];

const cmpBytes = (a, b) => Buffer.compare(Buffer.from(a), Buffer.from(b));
const md5 = (lines) => crypto.createHash("md5").update(lines.join("\n")).digest("hex");
const q = (s) => `'${s.replace(/'/g, "''")}'`;

export function generate(labLines) {
  const lines = labLines.filter(Boolean).sort(cmpBytes);
  const stray = lines.filter((l) => EXTRA.includes(l));
  if (stray.length) throw new Error(`lab already contains EXTRA lines (move them out of EXTRA): ${stray.join(", ")}`);
  const of = (s) => lines.filter((l) => l.startsWith(`${s}|`));
  const out = [];
  out.push(`-- GENERATED by scripts/security-lab/gen-production-assert.mjs from the security lab; regenerate it, never hand-edit it.`);
  out.push(`-- Privilege model of Production vs the lab built from every migration on this checkout (read-only, assert-only).`);
  out.push(`-- A section is PASS when Production's lines equal the lab's, after removing the EXTRA lines listed below.`);
  out.push(`-- Lab line counts: ${SECTIONS.map(([s]) => `${s}=${of(s).length}`).join(" ")}.`);
  out.push(`SET default_transaction_read_only = on;`);
  out.push("");
  out.push(MODEL.trim());
  out.push(`, extra(line) AS (VALUES ${EXTRA.map((l) => `(${q(l)})`).join(", ")})`);
  out.push(`, core AS (SELECT section, line FROM model WHERE line NOT IN (SELECT line FROM extra))`);
  out.push(`SELECT`);
  const items = [];
  for (const [s, label] of SECTIONS) {
    items.push(`  CASE WHEN ${q(md5(of(s)))} = (SELECT coalesce(md5(string_agg(line, E'\\n' ORDER BY line COLLATE "C")), md5('')) FROM core WHERE section = ${q(s)}) THEN 'PASS' ELSE 'FAIL' END AS ${label}_match_lab`);
    items.push(`  (SELECT count(*) FROM core WHERE section = ${q(s)}) AS ${label}_count`);
  }
  items.push(`  (SELECT count(*) FROM model WHERE section = 'L') AS direct_login_role_privileges`);
  items.push(`  (SELECT count(*) FROM model WHERE section = 'B') AS bypassrls_roles`);
  items.push(`  EXISTS (SELECT 1 FROM model WHERE line = 'B|OWNER') AS owner_bypassrls`);
  EXTRA.forEach((l, i) => items.push(`  EXISTS (SELECT 1 FROM model WHERE line = ${q(l)}) AS extra_${String(i + 1).padStart(2, "0")}_present`));
  out.push(items.join(",\n"));
  out.push(`;`);
  out.push(`-- extra_NN, in order: ${EXTRA.map((l, i) => `${String(i + 1).padStart(2, "0")}=${l}`).join("  ")}`);
  return out.join("\n") + "\n";
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === path.resolve(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1"));
if (isMain) {
  const [file, flag] = process.argv.slice(2);
  if (!file) { console.error("usage: gen-production-assert.mjs <lab-lines.txt> [--check]"); process.exit(2); }
  const text = generate(fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n").split("\n"));
  if (flag === "--check") {
    const cur = fs.existsSync(OUT) ? fs.readFileSync(OUT, "utf8").replace(/\r\n/g, "\n") : "";
    if (cur !== text) { console.error(`${path.relative(ROOT, OUT)} is stale — regenerate it from the security lab`); process.exit(1); }
    console.log(`${path.relative(ROOT, OUT)} is current`);
  } else {
    fs.writeFileSync(OUT, text);
    console.log(`wrote ${path.relative(ROOT, OUT)}`);
  }
}
